class Solution:
    def sumOfFlooredPairs(self, nums: List[int]) -> int:
        MOD = 10 ** 9 + 7
        mx = max(nums)
        cnt = [0] * (mx + 1)
        for x in nums:
            cnt[x] += 1
        pref = [0] * (mx + 1)
        for v in range(1, mx + 1):
            pref[v] = pref[v - 1] + cnt[v]
        ans = 0
        for d in range(1, mx + 1):
            if cnt[d] == 0:
                continue
            total = 0
            lo = d
            while lo <= mx:
                hi = min(mx, lo + d - 1)
                total += (lo // d) * (pref[hi] - pref[lo - 1])
                lo += d
            ans = (ans + cnt[d] * (total % MOD)) % MOD
        return ans

