    int sumOfFlooredPairs(vector<int>& nums) {
        const long long MOD = 1000000007LL;
        int mx = *max_element(nums.begin(), nums.end());
        vector<long long> cnt(mx + 1, 0), pref(mx + 1, 0);
        for (int x : nums) cnt[x]++;
        for (int v = 1; v <= mx; ++v) pref[v] = pref[v - 1] + cnt[v];
        long long ans = 0;
        for (long long d = 1; d <= mx; ++d) {
            if (!cnt[d]) continue;
            long long total = 0;
            for (long long lo = d; lo <= mx; lo += d) {
                long long hi = min((long long)mx, lo + d - 1);
                total += (lo / d) * (pref[hi] - pref[lo - 1]);
            }
            ans = (ans + cnt[d] * (total % MOD)) % MOD;
        }
        return (int)(ans % MOD);
    }
};

