class Solution {
    public int sumOfFlooredPairs(int[] nums) {
        final long MOD = 1_000_000_007L;
        int mx = 0;
        for (int x : nums) mx = Math.max(mx, x);
        long[] cnt = new long[mx + 1];
        long[] pref = new long[mx + 1];
        for (int x : nums) cnt[x]++;
        for (int v = 1; v <= mx; v++) pref[v] = pref[v - 1] + cnt[v];
        long ans = 0;
        for (long d = 1; d <= mx; d++) {
            if (cnt[(int) d] == 0) continue;
            long total = 0;
            for (long lo = d; lo <= mx; lo += d) {
                long hi = Math.min((long) mx, lo + d - 1);
                total += (lo / d) * (pref[(int) hi] - pref[(int) (lo - 1)]);
            }
            ans = (ans + cnt[(int) d] * (total % MOD)) % MOD;
        }
        return (int) ans;
    }
}

